import re
from nltk import word_tokenize
from collections import Counter

def task_func(input_str):
    """
    Remove special characters and punctuation using regex, normalize spaces,
    tokenize the text, and return a frequency dictionary of words.
    """
    if input_str is None:
        return {}

    text = str(input_str)

    # Replace non-alphanumeric characters (excluding whitespace) with spaces
    cleaned = re.sub(r"[^A-Za-z0-9\s]", " ", text)

    # Normalize repeated whitespace and lowercase for case-insensitive counting
    cleaned = re.sub(r"\s+", " ", cleaned).strip().lower()

    if not cleaned:
        return {}

    # Use NLTK tokenization if available; fall back to simple split if needed
    try:
        words = word_tokenize(cleaned)
    except Exception:
        words = cleaned.split()

    return dict(Counter(words))
